import { DamageApplied } from "../../components/DamageApplied.js";
import { recordDeathImpactFromDamage } from "../cleanupSystem.js";

export function deathImpactDamageReactionSystem(world) {
  for (const [, damage] of world.query(DamageApplied)) {
    recordDeathImpactFromDamage(world, damage);
  }
}

import { AggroState } from "../../components/AggroState.js";
import { DamageApplied } from "../../components/DamageApplied.js";
import { Faction } from "../../components/Faction.js";
import { Vitality } from "../../components/Vitality.js";
import { areFactionsHostile } from "../../utils/factionHostility.js";
import {
  addThreat,
  getThreatGenerationMultiplier,
  resolveThreatTarget,
} from "../../utils/threat.js";

function factionsHostile(world, sourceId, targetId) {
  const sourceFaction = String(world.get(sourceId, Faction)?.key || "");
  const targetFaction = String(world.get(targetId, Faction)?.key || "");
  return !!sourceFaction && !!targetFaction && areFactionsHostile(sourceFaction, targetFaction);
}

function canReceiveThreat(world, sourceId, targetId) {
  const source = Number(sourceId || 0) | 0;
  const target = Number(targetId || 0) | 0;
  if (!(source > 0) || !(target > 0) || source === target) return false;
  if (!world.isAlive(source) || !world.isAlive(target)) return false;
  if (!world.get(target, AggroState)) return false;
  const vit = world.get(target, Vitality);
  if (vit && (Number(vit.hp || 0) | 0) <= 0) return false;
  return factionsHostile(world, source, target);
}

export function threatDamageReactionSystem(world) {
  for (const [, damage] of world.query(DamageApplied)) {
    const owner = Number(damage.target || 0) | 0;
    const actor = Number(damage.source || 0) | 0;
    const value = Math.max(0, Number(damage.amount || 0) | 0);
    if (!(value > 0) || !canReceiveThreat(world, actor, owner)) continue;

    const mult = getThreatGenerationMultiplier(world, actor);
    addThreat(world, owner, actor, Math.max(1, Math.floor((value * mult) + 1e-6)), {
      kind: String(damage.cause || "damage"),
    });
    resolveThreatTarget(world, owner, { reason: "damage" });
  }
}

import { DamageApplied } from "../../components/DamageApplied.js";
import { SleepState } from "../../components/SleepState.js";
import { tryWakeActor } from "../../utils/sleep.js";

export function sleepDamageReactionSystem(world) {
  for (const [, damage] of world.query(DamageApplied)) {
    if (!(damage.amount > 0)) continue;
    const target = Number(damage.target || 0) | 0;
    const sleep = world.get(target, SleepState);
    if (!sleep || sleep.asleep !== true || sleep.wakeOnDamage === false) continue;
    tryWakeActor(world, target, {
      reason: "damage",
      intensity: Math.max(1, Number(damage.amount || 0)),
      source: Number(damage.source || 0) | 0,
    });
  }
}

import { AggroState, AGGRO_LEVELS, SEARCH_TURNS_ALERTED } from "../../components/AggroState.js";
import { DamageApplied } from "../../components/DamageApplied.js";
import { Position } from "../../components/Position.js";

export function aggroDamageReactionSystem(world) {
  for (const [, damage] of world.query(DamageApplied)) {
    if (!(damage.amount > 0)) continue;
    const target = Number(damage.target || 0) | 0;
    const source = Number(damage.source || 0) | 0;
    const aggro = world.get(target, AggroState);
    if (!aggro) continue;
    if (aggro.alertLevel === AGGRO_LEVELS.hunting) continue;

    const srcPos = (source && world.isAlive(source)) ? world.get(source, Position) : null;
    if (srcPos) {
      aggro.lastKnownX = srcPos.x | 0;
      aggro.lastKnownY = srcPos.y | 0;
    } else if (damage.at) {
      aggro.lastKnownX = damage.at.x | 0;
      aggro.lastKnownY = damage.at.y | 0;
    }

    aggro.alertLevel = AGGRO_LEVELS.alerted;
    aggro.targetId = 0;
    aggro.searchTurnsLeft = SEARCH_TURNS_ALERTED;

    const tPos = world.get(target, Position);
    if (tPos) {
      world.emit("status", {
        id: target,
        kind: "alert",
        at: { x: tPos.x | 0, y: tPos.y | 0 },
      });
    }
  }
}

import { DamageApplied } from "../../components/DamageApplied.js";
import { applyElectrocuted } from "../../utils/electrocute.js";

export function electrocuteDamageReactionSystem(world) {
  for (const [, damage] of world.query(DamageApplied)) {
    if (!(damage.amount > 0)) continue;
    const type = String(damage.type || "");
    if (type !== "electric" && type !== "lightning") continue;
    applyElectrocuted(world, Number(damage.target || 0) | 0);
  }
}

import { DamageApplied } from "../../components/DamageApplied.js";
import { applyItemDestructionForDamage } from "../itemDestructionSystem.js";

export function itemDamageReactionSystem(world) {
  for (const [, damage] of world.query(DamageApplied)) {
    applyItemDestructionForDamage(world, damage);
  }
}

